<script setup>
// 修复14：删除文档前添加 confirm() 确认，防止用户误操作丢失数据。
import { ref, nextTick } from 'vue'

defineProps({
  docs: Array,
  currentId: String
})
const emit = defineEmits(['load', 'delete', 'rename'])

const editingId = ref(null)
const editTitle = ref('')
const editInputRef = ref(null)

const startRename = doc => {
  editingId.value = doc.id
  editTitle.value = doc.title
  nextTick(() => editInputRef.value?.[0]?.focus())
}

const finishRename = doc => {
  if (editingId.value === doc.id) {
    emit('rename', { id: doc.id, title: editTitle.value })
    editingId.value = null
  }
}

const cancelRename = () => {
  editingId.value = null
}

// 修复14：删除前确认
const handleDelete = (doc) => {
  if (confirm(`确定要删除文档「${doc.title || '未命名文档'}」吗？此操作不可撤销。`)) {
    emit('delete', doc.id)
  }
}
</script>

<template>
  <div class="doc-list">
    <div class="list-header">
      <h3>📂 我的文档</h3>
    </div>

    <div v-if="docs.length === 0" class="empty-state">
      <span>暂无保存的文档</span>
    </div>

    <ul v-else class="list-content">
      <li
        v-for="doc in docs"
        :key="doc.id"
        class="doc-item"
        :class="{ active: currentId === doc.id }"
        @click="emit('load', doc)"
      >
        <div class="doc-main">
          <div v-if="editingId === doc.id" class="rename-box" @click.stop>
            <input
              ref="editInputRef"
              v-model="editTitle"
              @blur="finishRename(doc)"
              @keyup.enter="finishRename(doc)"
              @keyup.esc="cancelRename"
              class="rename-input"
            />
          </div>
          <span v-else class="doc-title" :title="doc.title">{{ doc.title || '未命名文档' }}</span>
          <span class="doc-date">{{ doc.createdAt.split(' ')[0] }}</span>
        </div>

        <div class="doc-actions">
          <button
            v-if="editingId !== doc.id"
            class="action-btn rename-btn"
            @click.stop="startRename(doc)"
            title="重命名"
          >✎</button>
          <!-- 修复14：绑定带确认的 handleDelete -->
          <button
            class="action-btn delete-btn"
            @click.stop="handleDelete(doc)"
            title="删除文档"
          >×</button>
        </div>
      </li>
    </ul>
  </div>
</template>

