  cursor: pointer; transition: all 0.2s ease;
}
.doc-item:hover { background: var(--bg-hover); }
.doc-item.active { border-color: var(--color-accent); background: var(--bg-hover); }

.doc-main {
  display: flex; flex-direction: column;
  overflow: hidden; flex: 1; margin-right: 10px;
}
.doc-title {
  font-weight: 500; font-size: 16px; color: var(--text-primary);
  white-space: nowrap; overflow: hidden; text-overflow: ellipsis;
}
.rename-input {
  width: 100%; font-size: 14px; padding: 2px 4px;
  border: 1px solid var(--color-accent); border-radius: 4px;
  background: var(--bg-app); color: var(--text-primary); outline: none;
}
